'use strict';

var mannWhitneyU = require( './../lib' );

var out = mannWhitneyU( [ 7, 8, 9 ], [ 1, 2, 3 ] );
console.log( out );

out = mannWhitneyU( [ 10, 11, 10, 12 ], [ 9, 11, 10, 10 ] );
console.log( out );

out = mannWhitneyU( [ 7, 8, 9 ], [ 1, 2, 3 ], {
	'alpha': 0.05,
	'alternative': 'greater'
});
console.log( out );

out = mannWhitneyU( [ 5, 6, 7, 8 ], [ 1, 2, 3, 4 ], {
	'alpha': 0.05,
	'alternative': 'less'
});
console.log( out );
